// Independent source-oracle matrix plus actual asynchronous persistence flows.
void MagicBirthCatalogWorker(const GameSqlConfig& player,const std::shared_ptr<const auriga::item::ItemCatalog>& catalog,
    const std::string& password,const std::string& path,const std::vector<BulkSource>& sources,
    const std::vector<std::array<std::vector<auriga::item::BonusEntry>,3>>& expected,const std::set<unsigned>& samples)
{
    using namespace auriga::item;const ItemOwner probe{ItemOwnerKind::Character,14000};const std::array bags{ItemStorageLayout{{probe,ItemStorageKind::Inventory,1},5,9,4}};
    for(unsigned n=0;n<sources.size();++n)for(unsigned policy=0;policy<3;++policy) {
        auto spec=sources[n].grant;spec.createdAtUtcMs=1794770000000ULL;spec.tryMagic=policy>0;if(policy==2)spec.magicChanceBp=10000;
        const std::array<std::uint8_t,16> op{0xA7,static_cast<std::uint8_t>(n),static_cast<std::uint8_t>(n>>8)};const std::array ids{ItemInstanceId::Create(14000000u+n).value()};
        auto grant=MakeGrantCommit(*catalog,op,{probe,1,1},bags,{},spec,ids);if(!grant)std::cout<<"MAGIC_PROBE_FAILURE="<<n<<" policy="<<policy<<std::endl;
        Check(grant.has_value(),"every original magic birth policy issues successfully");const auto& item=grant->items[0].after;
        Check(InstanceAttributeContributions(*catalog,item.key,item.attributes).value()==expected[n][policy],"independent Python SHA, source tier and weight reference matches exactly");
    }
    CAsyncSQL sql;sql.SetTimeouts(5);sql.SetRetryConnectionErrors(false);Check(sql.Setup("127.0.0.1","root",password.c_str(),"player","utf8mb4",true,player.port),"magic private SQL connects");auto& store=runtime::ItemStore::Instance();Check(store.Start(player,catalog,"source-magic-birth-worker").has_value(),"magic actual item worker starts");
    const auto issued=static_cast<std::uint64_t>(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count());
    for(const auto n:samples)for(unsigned policy=0;policy<3;++policy) {
        std::cout<<"MAGIC_SQL_CASE="<<n<<" policy="<<policy<<std::endl;const auto key=sources[n].grant.key;const ItemOwner owner{ItemOwnerKind::Character,15000u+n*3+policy};const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,4},ItemStorageLayout{{owner,ItemStorageKind::Equipment,1},28,1,1}};
        Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,{}).has_value(),"magic owner provisioned");auto state=persistence::LoadCurrentItemOwner(sql,*catalog,owner).value();unsigned serial=0;bool replay=false;
        const auto op=[&](){++serial;return std::array<std::uint8_t,16>{0xA8,static_cast<std::uint8_t>(n),static_cast<std::uint8_t>(n>>8),static_cast<std::uint8_t>(policy),static_cast<std::uint8_t>(serial)};};
        const auto apply=[&](const ItemCommit& commit){std::optional<runtime::CommitOutcome> got;Check(runtime::RequestCommit(owner,state.fence.sessionGeneration,commit,[&](auto out){got=std::move(out);}),"magic commit queued");for(unsigned spin=0;!got && spin<1000;++spin){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(10));}Check(got && got->write && got->state,"magic commit saves and reloads");replay=got->write->replay;state=*got->state;};
        const auto find=[&](ItemInstanceId id)->const PersistentItem&{const auto i=std::ranges::find(state.items,id,&PersistentItem::id);Check(i!=state.items.end(),"magic subject exists");return *i;};
        const auto output=[&](const char* phase){for(unsigned kind=0;kind<2;++kind){auto bytes=kind ? EncodeTypedItemDetails(*catalog,state.items).value() : EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value();std::ofstream f(path+"."+std::to_string(n)+"."+std::to_string(policy)+"."+phase+(kind ? ".details.hex" : ".inventory.hex"));for(auto b:bytes){auto v=std::to_integer<unsigned>(b);f<<"0123456789abcdef"[v>>4]<<"0123456789abcdef"[v&15];}f<<'\n';Check(f.good(),"magic actual packets exported");}};
        auto spec=sources[n].grant;spec.createdAtUtcMs=issued;spec.tryMagic=policy>0;if(policy==2)spec.magicChanceBp=10000;
        const auto ids=runtime::PeekInstanceIds(1);runtime::SpendInstanceIds(1);const auto grant=MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,spec,ids).value();apply(grant);const auto attributes=find(ids[0]).attributes;std::cout<<"MAGIC_SQL_BIRTH="<<n<<" "<<policy<<" "<<ids[0].Value();for(const auto b:InstanceAttributeContributions(*catalog,key,attributes).value())std::cout<<" "<<static_cast<unsigned>(b.bonus)<<":"<<b.valueScaled;std::cout<<std::endl;output("born");const auto saved=state.items;apply(grant);Check(replay && saved==state.items,"magic receipt replay cannot redraw or duplicate");
        const auto relog=[&](){const auto before=state.items;const auto generation=persistence::ClaimOwnerSession(sql,*catalog,owner).value();state=persistence::LoadItemOwner(sql,*catalog,owner,generation).value();Check(before==state.items,"magic exact birth survives a new SQL session");};relog();output("relogged");
        EquipContext actor{255,0,0,issued+1000};const auto* use=catalog->FindUsePolicy(catalog->Find(key)->base.usePolicy);while(!(use->allowedClasses&(1u<<actor.characterClass)))++actor.characterClass;while(!(use->allowedSexes&(1u<<actor.sex)))++actor.sex;
        const auto* costume=std::get_if<ItemCostumeRow>(&catalog->Find(key)->category);
        if(costume && costume->kind==CostumeKind::Weapon) {
            auto matched=std::ranges::find_if(catalog->Entries(),[&](const auto& entry){const auto* w=std::get_if<ItemWeaponRow>(&entry.second.category);const auto* p=catalog->FindUsePolicy(entry.second.base.usePolicy);return w && w->subtype==*costume->weapon && p && (p->allowedClasses&(1u<<actor.characterClass)) && (p->allowedSexes&(1u<<actor.sex)) && !entry.second.base.retired && !FindWearableClock(*catalog,entry.first);});Check(matched!=catalog->Entries().end(),"weapon costume has a compatible native real weapon");
            const auto support=runtime::PeekInstanceIds(1);runtime::SpendInstanceIds(1);apply(MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,{matched->first},support).value());apply(MakeEquipCommit(*catalog,op(),state.fence,state.storages,state.items,support[0],actor).value());
        }
        apply(MakeEquipCommit(*catalog,op(),state.fence,state.storages,state.items,ids[0],actor).value());Check(find(ids[0]).attributes==attributes,"equip preserves exact original magic attributes");Check(BuildEquipmentStats(*catalog,owner,state.items).has_value(),"magic attributes contribute to native equipment stats");output("equipped");
        apply(MakeUnequipCommit(*catalog,op(),state.fence,state.storages,state.items,ids[0],{ItemStorageKind::Inventory,1,20},actor).value());Check(find(ids[0]).attributes==attributes,"unequip preserves birth and removes equipment contribution");relog();output("moved");
    }
    unsigned boxes=0,rareCases=0;for(const auto& [key,entry]:catalog->Entries())if(const auto* box=std::get_if<ItemContainerRow>(&entry.category);box && (box->kind==ContainerKind::Use || box->kind==ContainerKind::Locked)) {
        if(!ValidateContainerContents(*catalog,key))std::cout<<"CONTAINER_ADMISSION_DENIED="<<key.LocalId()<<std::endl;else ++boxes;
        const auto* loot=catalog->FindLoot(*box->lootProfile);std::uint32_t offset=0;
        for(const auto& reward:loot->Data().entries) {
            const auto roll=offset;offset+=reward.weight;if(!reward.rareAttributeChanceBp)continue;
            const auto n=rareCases++;Check(box->kind==ContainerKind::Use && loot->Data().mode==LootPickMode::WeightedOne,"source rare box admits a single weighted reward");
            const ItemOwner owner{ItemOwnerKind::Character,60000u+n};const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,4}};const std::array wallets{ItemWallet{owner,WalletCurrency::Gold,1,0}};
            Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,wallets).has_value(),"source rare box owner provisioned");auto state=persistence::LoadCurrentItemOwner(sql,*catalog,owner).value();bool replay=false;
            const auto apply=[&](const ItemCommit& commit){std::optional<runtime::CommitOutcome> got;Check(runtime::RequestCommit(owner,state.fence.sessionGeneration,commit,[&](auto out){got=std::move(out);}),"rare opening queued");for(unsigned spin=0;!got && spin<1000;++spin){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(10));}Check(got && got->write && got->state,"rare opening persists");replay=got->write->replay;state=*got->state;};
            const std::array<std::uint8_t,16> grantOp{0xA9,static_cast<std::uint8_t>(n),1},openOp{0xA9,static_cast<std::uint8_t>(n),2};const auto boxIds=runtime::PeekInstanceIds(1);runtime::SpendInstanceIds(1);ItemGrant spec{key};spec.createdAtUtcMs=issued;apply(MakeGrantCommit(*catalog,grantOp,state.fence,state.storages,state.items,spec,boxIds).value());const auto before=state.items[0];
            const auto write=[&](const std::string& phase,const std::string& kind,const std::vector<std::byte>& bytes){std::ofstream f(path+".box."+std::to_string(n)+"."+phase+"."+kind+".hex");for(auto b:bytes){auto v=std::to_integer<unsigned>(b);f<<"0123456789abcdef"[v>>4]<<"0123456789abcdef"[v&15];}f<<'\n';Check(f.good(),"source rare opening packet exports");};
            write("ready","inventory",EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value());write("ready","details",EncodeTypedItemDetails(*catalog,state.items).value());write("ready","container",EncodeContainerOpening(*catalog,140,&before,nullptr,state.fence.revision,ContainerOpeningStatus::Ready,{},{}).value());
            const auto ids=runtime::PeekInstanceIds(1);runtime::SpendInstanceIds(1);const auto opening=MakeContainerOpeningCommit(*catalog,openOp,state.fence,state.storages,state.items,state.wallets,{boxIds[0],{},{255,0,0,false},issued},ids,[&](auto){return roll;});Check(opening && opening->won==std::vector<std::uint16_t>{reward.entry},"actual rare source row can be selected and opened");apply(opening->commit);Check(state.items.size()==1 && state.items[0].key==*reward.item,"actual source box consumed and exact rare reward saved");
            ItemGrant expectedReward{*reward.item,reward.refinementLevel,static_cast<std::uint32_t>(reward.amount)};expectedReward.createdAtUtcMs=issued;expectedReward.tryMagic=true;expectedReward.magicChanceBp=reward.rareAttributeChanceBp;
            const auto expectedGrant=MakeGrantCommit(*catalog,openOp,state.fence,state.storages,{},expectedReward,ids).value();Check(state.items[0].attributes==expectedGrant.items[0].after.attributes,"source rare chance reaches real item factory");
            std::cout<<"MAGIC_BOX_BIRTH="<<n<<" "<<static_cast<unsigned>(reward.item->Category())<<" "<<reward.item->LocalId()<<" "<<reward.refinementLevel<<" "<<reward.rareAttributeChanceBp<<" "<<ids[0].Value();for(const auto b:InstanceAttributeContributions(*catalog,*reward.item,state.items[0].attributes).value())std::cout<<" "<<static_cast<unsigned>(b.bonus)<<":"<<b.valueScaled;std::cout<<std::endl;
            const auto output=[&](const char* phase){write(phase,"inventory",EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value());write(phase,"details",EncodeTypedItemDetails(*catalog,state.items).value());write(phase,"container",EncodeContainerOpening(*catalog,140,&before,nullptr,state.fence.revision,ContainerOpeningStatus::Opened,{},opening->won).value());};output("opened");const auto saved=state.items;apply(opening->commit);Check(replay && state.items==saved,"rare opening replay cannot redraw or duplicate");const auto generation=persistence::ClaimOwnerSession(sql,*catalog,owner).value();state=persistence::LoadItemOwner(sql,*catalog,owner,generation).value();Check(state.items==saved,"source rare reward survives relog");output("relogged");
        }
    }
    store.Stop();std::cout<<"SOURCE_MAGIC_BIRTH_WORKER=SUCCESS states="<<sources.size()<<" policies=3 sql_samples="<<samples.size()<<" admitted_boxes="<<boxes<<" rare_rewards="<<rareCases<<" checks="<<checks<<std::endl;
}

